function onPointerEnd(event){if(event.pointerType!=='touch')return;if(!state.pointers.has(event.pointerId)){if(state.crosshairPinned)stopEvent(event);return}stopEvent(event);const point=state.pointers.get(event.pointerId),finished=state.gesture;state.pointers.delete(event.pointerId);state.lastTouchEndAt=performance.now();clearHold();try{if(canvas.hasPointerCapture(event.pointerId))canvas.releasePointerCapture(event.pointerId)}catch(_){}if(finished?.type==='crosshair'&&point?.zone==='plot'&&!finished.moved&&!finished.activatedByHold){const now=performance.now();if(now-state.lastTapAt<=DOUBLE_TAP_MS){state.lastTapAt=0;clearPinnedCrosshair();return}state.lastTapAt=now}if(!state.crosshairPinned&&state.pointers.size>=2){startPinch();return}chart.gesture=null;state.gesture=null;chart.setInteractionClass(point?.zone||'plot');redraw()}
