function selectCrosshairPrice(){const p=currentCrosshairPrice();if(!(Number(p)>0))return;canvas.dispatchEvent(new CustomEvent('galka:select-price',{detail:{price:Number(p),source:'touch-plus',timeSec:(()=>{const w=chart.visibleWindow?.(),g=chart.geometry?.();if(!chart.crosshair||!w?.all?.length||!g)return 0;const ratio=clamp((chart.crosshair.x-g.left)/g.plotWidth,0,1),logical=w.start+ratio*w.count,base=Math.floor(logical),fraction=logical-base;let interval=300;for(let i=w.all.length-1;i>0;i--){const d=Number(w.all[i]?.time)-Number(w.all[i-1]?.time);if(d>0){interval=d;break}}let t;if(base<0)t=Number(w.all[0]?.time||0)+base*interval;else if(base>=w.all.length)t=Number(w.all.at(-1)?.time||0)+(base-w.all.length+1)*interval;else t=Number(w.all[base]?.time||0);return t+fraction*interval})()}}));clearPinnedCrosshair()}
